mapper.select:
SELECT pl.log_id AS logId, pl.shop_id AS shopId, s.shop_name AS shopName, pl.user_id AS userId, u.nickname AS nickname, u.phone AS phone, pl.action_type AS actionType, pl.pre_base_points AS preBasePoints, pl.pre_bonus_points AS preBonusPoints, pl.change_base AS changeBase, pl.change_bonus AS changeBonus, pl.after_base_points AS afterBasePoints, pl.after_bonus_points AS afterBonusPoints, pl.status AS status, pl.remark AS remark, pl.coupon_id AS couponId, pl.create_time AS createTime, pl.consume_time AS consumeTime, (ABS(IFNULL(pl.change_base, 0)) + ABS(IFNULL(pl.change_bonus, 0))) AS consumePoints FROM mobi_points_log pl INNER JOIN mobi_user u ON u.user_id = pl.user_id INNER JOIN mobi_shop s ON s.id = pl.shop_id
AND pl.shop_id = #{query.shopId}
AND pl.user_id = #{query.userId}
AND s.shop_name LIKE CONCAT('%', #{query.shopName}, '%')
AND ( u.phone LIKE CONCAT('%', #{query.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%') )
AND u.nickname LIKE CONCAT('%', #{query.keyword}, '%')
AND u.nickname LIKE CONCAT('%', #{query.nickname}, '%')
AND u.phone LIKE CONCAT('%', #{query.phone}, '%')
AND pl.action_type = #{query.actionType}
AND pl.pre_base_points = #{query.preBasePoints}
AND pl.pre_bonus_points = #{query.preBonusPoints}
AND pl.change_base = #{query.changeBase}
AND pl.change_bonus = #{query.changeBonus}
AND pl.after_base_points = #{query.afterBasePoints}
AND pl.after_bonus_points = #{query.afterBonusPoints}
AND pl.status = #{query.status}
AND pl.status != #{query.excludeStatus}
ORDER BY CASE WHEN u.phone LIKE CONCAT('%', #{query.keyword}, '%') THEN 0 ELSE 1 END, pl.create_time DESC
ORDER BY pl.create_time DESC
ORDER BY (ABS(IFNULL(pl.change_base, 0)) + ABS(IFNULL(pl.change_bonus, 0))) DESC, pl.create_time DESC
ORDER BY pl.create_time DESC, (ABS(IFNULL(pl.change_base, 0)) + ABS(IFNULL(pl.change_bonus, 0))) DESC
